<template><PageShell title="财务凭证" tcode="FB03"><el-card><div class="toolbar"><el-select v-model="filters.blart" clearable placeholder="凭证类型"><el-option label="SA" value="SA" /><el-option label="KZ" value="KZ" /><el-option label="DZ" value="DZ" /></el-select><el-date-picker v-model="filters.date" type="date" value-format="YYYY-MM-DD" /><el-button @click="load">查询</el-button></div><el-table :data="rows" border stripe><el-table-column prop="belnr" label="凭证号" /><el-table-column prop="blart" label="类型" /><el-table-column prop="budat" label="过账日期" /><el-table-column prop="headerText" label="摘要" /><el-table-column prop="reversedBy" label="冲销凭证" /><el-table-column label="操作"><template #default="{row}"><el-button link @click="show(row)">明细</el-button><el-button v-if="!row.reversedBy && row.blart!=='AB'" link type="danger" @click="reverse(row)">冲销</el-button></template></el-table-column></el-table></el-card><el-drawer v-model="visible" title="财务凭证明细" size="65%"><el-table :data="selected?.items||[]" border><el-table-column prop="saknr" label="科目" /><el-table-column prop="shkzg" label="借贷" /><el-table-column prop="amount" label="金额" /><el-table-column prop="kostl" label="成本中心" /><el-table-column prop="lifnr" label="供应商" /><el-table-column prop="kunnr" label="客户" /><el-table-column prop="text" label="文本" /></el-table></el-drawer></PageShell></template>
<script setup>
import { onMounted, reactive, ref } from 'vue'; import { ElMessageBox } from 'element-plus'; import PageShell from '../../components/PageShell.vue'; import { fiApi } from '../../api'; const rows=ref([]),filters=reactive({blart:'',date:''}),visible=ref(false),selected=ref(null);async function load(){const r=await fiApi.documents(filters);rows.value=r.records||r||[]};async function show(r){selected.value=await fiApi.document(r.belnr);visible.value=true};async function reverse(r){await ElMessageBox.confirm('确认冲销该凭证？','提示');await fiApi.reverse(r.belnr);load()};onMounted(load)
</script>
